import React, { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { clearPermissionsCache } from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../store/hooks';
import { logout } from '../../store/slices/authSlice';
import { navigateInAppPath } from '../../router/navigateInAppPath';

const AUTH_RETURN_URL_KEY = 'linm:auth:return-url';

/**
 * Shell logout route (/logout). Clears backend session + Redux + cache, then /login.
 * Nav sidebar and cross-tab listeners should navigate here (not /login only).
 */
const LogoutPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const startedRef = useRef(false);

  useEffect(() => {
    if (startedRef.current) return;
    startedRef.current = true;

    sessionStorage.removeItem(AUTH_RETURN_URL_KEY);
    clearPermissionsCache();

    void dispatch(logout()).finally(() => {
      navigateInAppPath('/login', navigate, { replace: true });
    });
  }, [dispatch, navigate]);

  return (
    <div style={{ padding: '2rem', textAlign: 'center' }} role="status" aria-live="polite">
      Đang đăng xuất...
    </div>
  );
};

export default LogoutPage;
