import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { setUser } from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { login, clearError } from '../../store/slices/authSlice';
import { addToast } from '../../store/slices/uiSlice';
import { seedStandalonePermissions } from '../../dev/seedStandalonePermissions';
import { seedStandaloneAuth, STANDALONE_MOCK_USER } from '../../standalone/mockAuth';
import styles from './LoginPage.module.css';
import { Button } from '../../components/common/Button';
import { Card } from '../../components/common/Card';
import { Input } from '../../components/common/Input';
import { ChangePasswordModal } from '../../components/auth/ForceChangePasswordSlideout';
import { companyBrandingService, CompanyBranding } from '../../services/companyBranding';
import { resolveShellIcon, resolveShellNavMain, resolveShellTitle, resolveShellSubTitle, SHELL_ICON_PATH } from '../../config/shellBranding';
import { linmLogo128 } from '@linm-soft-org/linm-web-common-components';

const LoginPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { loading, error, isAuthenticated, requirePasswordChange } = useAppSelector((state) => state.auth);

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [branding, setBranding] = useState<CompanyBranding | null>(() => companyBrandingService.get());

  useEffect(() => {
    // Clear any previous errors when component mounts
    dispatch(clearError());
  }, [dispatch]);

  // Re-read branding in case it was fetched asynchronously after mount
  // (e.g. when Root-App captured a /company/{code} URL before redirecting here)
  useEffect(() => {
    setBranding(companyBrandingService.get());
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!username || !password) {
      dispatch(addToast({
        message: 'Vui lòng nhập tên đăng nhập và mật khẩu',
        type: 'error',
      }));
      return;
    }

    try {
      await dispatch(login({ username, password })).unwrap();
      dispatch(addToast({
        message: 'Đăng nhập thành công!',
        type: 'success',
      }));
      // Navigation will happen via useEffect
    } catch (error: any) {
      // Auth slice error state also shows inline form error
      const message = error instanceof Error ? error.message : 'Tên đăng nhập hoặc mật khẩu không đúng';
      dispatch(addToast({ message, type: 'error' }));
    }
  };

  const handleDevSkipLogin = () => {
    seedStandaloneAuth(true);
    seedStandalonePermissions();
    dispatch(setUser(STANDALONE_MOCK_USER));
    dispatch(addToast({ message: 'Dev: đã bỏ qua đăng nhập', type: 'info' }));
    navigate('/dev', { replace: true });
  };

  const pendingCompanyCode = typeof window !== 'undefined'
    ? localStorage.getItem('pending_company_code')
    : null;
  const useCompanyLogo = Boolean(pendingCompanyCode && branding?.logoUrl?.trim());
  const logoSrc = useCompanyLogo ? branding!.logoUrl! : resolveShellIcon(linmLogo128);
  const loginTitle = resolveShellTitle();
  const loginSubTitle = resolveShellSubTitle();
  const navLabel = resolveShellNavMain();

  return (
    <div className={styles.container}>
      <ChangePasswordModal isOpen={isAuthenticated && !!requirePasswordChange} isForced={true} />
      <Card className={styles.card}>
        <div className={styles.logo}>
          <img
            src={logoSrc}
            alt={branding?.name || navLabel}
            onError={(e) => {
              const img = e.currentTarget;
              const shellFallback = resolveShellIcon(SHELL_ICON_PATH);
              if (img.src !== shellFallback && !img.src.endsWith(SHELL_ICON_PATH)) {
                img.src = shellFallback;
                return;
              }
              if (img.src !== linmLogo128) img.src = linmLogo128;
            }}
          />
        </div>
        {branding && <p className={styles.companyName}>{branding.name}</p>}
        <h1 className={styles.title}>{loginTitle}</h1>
        <p className={styles.subtitle}>{loginSubTitle}</p>

        <form onSubmit={handleLogin} className={styles.form}>
          {error && (
            <div className={styles.errorMessage}>
              <i className="fas fa-exclamation-circle"></i>
              <span>{error}</span>
            </div>
          )}

          <div className={styles.inputGroup}>
            <label htmlFor="username">Tên đăng nhập</label>
            <Input
              id="username"
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Nhập tên đăng nhập"
              required
              autoComplete="username"
              disabled={loading}
            />
          </div>

          <div className={styles.inputGroup}>
            <label htmlFor="password">Mật khẩu</label>
            <div className={styles.passwordWrapper}>
              <Input
                id="password"
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Nhập mật khẩu"
                required
                autoComplete="current-password"
                disabled={loading}
                className={styles.passwordInput}
              />
              <button
                type="button"
                className={styles.togglePassword}
                onClick={() => setShowPassword((v) => !v)}
                tabIndex={-1}
                aria-label={showPassword ? 'Ẩn mật khẩu' : 'Hiện mật khẩu'}
              >
                <i className={showPassword ? 'fas fa-eye-slash' : 'fas fa-eye'}></i>
              </button>
            </div>
          </div>

          <Button type="submit" fullWidth loading={loading} disabled={!username || !password}>
            {loading ? 'Đang đăng nhập...' : 'Đăng nhập'}
          </Button>

          {import.meta.env.VITE_STANDALONE === 'true' && (
            <Button
              type="button"
              variant="secondary"
              fullWidth
              className={styles.devSkipBtn}
              onClick={handleDevSkipLogin}
              disabled={loading}
            >
              Dev: Bỏ qua đăng nhập
            </Button>
          )}
        </form>

      </Card>
    </div>
  );
};

export default LoginPage;
